CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, timezone TEXT NOT NULL DEFAULT 'America/Los_Angeles', start_weight REAL DEFAULT 88, goal_weight REAL DEFAULT 70);
CREATE TABLE IF NOT EXISTS daily_logs (profile_id TEXT NOT NULL, log_date TEXT NOT NULL, walk_minutes INTEGER NOT NULL DEFAULT 0, walk_completed INTEGER NOT NULL DEFAULT 0, chai_count INTEGER NOT NULL DEFAULT 0, notes TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(profile_id, log_date));
CREATE TABLE IF NOT EXISTS meals (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, log_date TEXT NOT NULL, name TEXT NOT NULL, portion TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS measurements (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, log_date TEXT NOT NULL, weight_kg REAL, waist_cm REAL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS push_subscriptions (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, endpoint TEXT NOT NULL UNIQUE, p256dh TEXT NOT NULL, auth TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_deliveries (profile_id TEXT NOT NULL, log_date TEXT NOT NULL, reminder_type TEXT NOT NULL, sent_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(profile_id, log_date, reminder_type));
